+  Assert.equal(thread.threadKey, 1);
+  Assert.equal(thread.numChildren, 4);
+  Assert.equal(thread.getRootHdr().messageId, "message1@invalid");
+  Assert.equal(thread.newestMsgDate, new Date("2025-06-02").valueOf() / 1000);
+});
